using System.Data;
using System.Text.Json;
using ContentOS.Application;
using ContentOS.Contracts;
using ContentOS.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
namespace ContentOS.Infrastructure;

public sealed partial class CommerceWorkbench(CoreDbContext db, CustomerWorkbench customers, ICreationStudio creations, IEnumerable<ICommerceDelivery> delivery) : ICommerceWorkbench
{
    private static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web);
    private static string Json<T>(T x) => JsonSerializer.Serialize(x, Options); private static T Read<T>(string s) => JsonSerializer.Deserialize<T>(s, Options)!; private static string Hash(object x) => EditorialBinding.Hash(x);
    private static Guid Op(Guid id, string kind) => new(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(id + ":commerce.v1:" + kind))[..16]);
    private async Task<T> Change<T>(Guid tenant, Func<Task<T>> action, CancellationToken ct) { db.ChangeTracker.Clear(); await using var tx = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct); await db.Database.ExecuteSqlInterpolatedAsync($"DECLARE @r int;EXEC @r=sys.sp_getapplock @Resource={"ContentOS.Commerce:" + tenant},@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000;IF @r<0 THROW 51000,'Commerce lock unavailable',1;", ct); try { var result = await action(); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return result; } catch { await tx.RollbackAsync(CancellationToken.None); db.ChangeTracker.Clear(); throw; } }
    private async Task Admin(CoreScope s, CancellationToken ct) { if (!await db.Members.AnyAsync(x => x.TenantId == s.TenantId && x.Actor == s.Actor && x.Permission == "Administrator", ct)) throw new CoreAccessException(); }
    private static CoreScope Staff(CustomerScope s) => new(s.TenantId, s.Principal.Identity!.Name!);
    private ICommerceDelivery Adapter(string key) => delivery.SingleOrDefault(x => x.Key == key && x.Qualification == "OfflineFixture") ?? throw new RuntimeValidationException("Only deployed private fixture fulfillment is qualified.");
    private async Task Guard(CommerceProduct p, CancellationToken ct) { CreationRules.Require(p.Enabled && p.PackageJson != null, "Licensed product is withdrawn."); await ((CreationStudio)creations).AssertLicensedRevision(p.TenantId, p.UserId, p.CreationId, p.ContentVersion, p.ContentSha256, ct); }
    internal async Task ValidateDelivery(Guid tenant, Guid orderId, CancellationToken ct)
    {
        var order = await db.CommerceOrders.AsNoTracking().SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == orderId, ct) ?? throw new CoreAccessException();
        await CurrentPaid(order, ct);
        await Guard(await db.CommerceProducts.AsNoTracking().SingleAsync(x => x.TenantId == tenant && x.Id == order.ProductId, ct), ct);
    }
    private static CommerceProductView View(CommerceProduct p) { var r = Read<CommerceProductRequest>(p.SettingsJson); return new(p.Id, p.Key, p.Version, p.Kind, r.Currency, r.PriceMinor, p.ContentVersion, p.ContentSha256, r.License, p.Enabled, true); }
    public async Task<Guid> ProductAsync(CustomerScope s, CommerceProductRequest r, CancellationToken ct)
    {
        var user = await customers.MeAsync(s, ct); await Admin(Staff(s), ct); CreationRules.Require(user.AdultAttested && r.OperationId != Guid.Empty && r.Version > 0 && r.Kind is "Book" or "Comic" or "LearningPack" or "Institutional", "Authorized adult publisher and supported pilot offer required."); CustomerRules.Key(r.Key); CustomerRules.Key(r.License.ContractReference);
        CreationRules.Require(r.License.Mode == "PrivateTest" && r.License.PrivateSharingConsent && r.License.Days is > 0 and <= 730 && r.License.Seats is > 0 and <= 100 && (r.Kind == "Institutional" || r.License.Seats == 1) && r.License.UpdatePolicy is "PinnedVersionNotifyCorrections" or "WithdrawOnCorrection" && r.License.Disclosure.Length <= 1000, "Explicit bounded private-test license/consent/update policy required; commercial launch is gated.");
        var pack = await creations.ExportAsync(s, r.CreationId, ct); var source = await db.Creations.AsNoTracking().SingleAsync(x => x.Id == r.CreationId, ct); var universe = await db.CreationTemplates.Where(x => x.Id == source.TemplateId).Select(x => x.UniverseId).SingleAsync(ct);
        var id = await Change(s.TenantId, async () => { var old = await db.CommerceProducts.SingleOrDefaultAsync(x => x.TenantId == s.TenantId && x.OperationId == r.OperationId, ct); if (old != null) { CreationRules.Require(old.UserId == user.Id && old.Fingerprint == Hash(r), "Catalog replay differs."); return old.Id; } CreationRules.Require(!await db.CommerceProducts.AnyAsync(x => x.TenantId == s.TenantId && x.Key == r.Key && x.Version >= r.Version, ct), "Append a new offer version."); var p = new CommerceProduct { Id = Guid.NewGuid(), TenantId = s.TenantId, UserId = user.Id, UniverseId = universe, OperationId = r.OperationId, Fingerprint = Hash(r), Key = r.Key, Version = r.Version, CreationId = r.CreationId, ContentVersion = pack.Version, ContentSha256 = pack.Sha256, Kind = r.Kind, SettingsJson = Json(r), PackageJson = Json(pack) }; db.CommerceProducts.Add(p); return p.Id; }, ct);
        var product = await db.CommerceProducts.AsNoTracking().SingleAsync(x => x.Id == id, ct); if (product.CustomerProductId == null) { var price = await customers.ProductAsync(Staff(s), new(Op(id, "price"), "commerce-" + id.ToString("N"), 1, r.Kind == "Institutional" ? "Institutional" : "Digital", r.Currency, r.PriceMinor, 0, r.License.Days, ["license:" + id.ToString("N")], universe, r.Kind == "Institutional" ? "InstitutionalContract" : "BooksComicsPacks"), ct); await Change(s.TenantId, async () => { var p = await db.CommerceProducts.SingleAsync(x => x.Id == id, ct); CreationRules.Require(p.CustomerProductId == null || p.CustomerProductId == price, "Original price differs."); p.CustomerProductId = price; return true; }, ct); }
        return id;
    }
    public async Task<CommerceProductView[]> ProductsAsync(CustomerScope s, CancellationToken ct) { await customers.MeAsync(s, ct); return (await db.CommerceProducts.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.Enabled && x.CustomerProductId != null).OrderBy(x => x.Key).ThenByDescending(x => x.Version).Take(100).ToArrayAsync(ct)).Select(View).ToArray(); }
    public Task<Guid> RouteAsync(CoreScope s, CommerceRouteRequest r, CancellationToken ct) => Change(s.TenantId, async () => { await Admin(s, ct); CustomerRules.Key(r.Key); CustomerRules.Key(r.Account); Adapter(r.Adapter); CreationRules.Require(r.OperationId != Guid.Empty && r.Version > 0, "Versioned fixture route required."); var old = await db.CommerceRoutes.SingleOrDefaultAsync(x => x.TenantId == s.TenantId && x.OperationId == r.OperationId, ct); if (old != null) { CreationRules.Require(old.Key == r.Key && old.Version == r.Version && old.Adapter == r.Adapter && old.Account == r.Account, "Delivery route replay differs."); return old.Id; } if (r.Active) { foreach (var x in await db.CommerceRoutes.Where(x => x.TenantId == s.TenantId && x.Active).ToArrayAsync(ct)) x.Active = false; await db.SaveChangesAsync(ct); } var row = new CommerceRoute { Id = Guid.NewGuid(), TenantId = s.TenantId, OperationId = r.OperationId, Key = r.Key, Version = r.Version, Adapter = r.Adapter, Account = r.Account, Active = r.Active }; db.CommerceRoutes.Add(row); return row.Id; }, ct);
    private async Task<CommerceOrder> Own(CustomerScope s, Guid id, CancellationToken ct) { var u = await customers.MeAsync(s, ct); return await db.CommerceOrders.SingleOrDefaultAsync(x => x.TenantId == s.TenantId && x.UserId == u.Id && x.Id == id, ct) ?? throw new CoreAccessException(); }
    public async Task<Guid> PurchaseAsync(CustomerScope s, CommercePurchase r, CancellationToken ct)
    {
        var user = await customers.MeAsync(s, ct); CustomerRules.Key(r.Acquisition);
        var id = await Change(s.TenantId, async () => { var old = await db.CommerceOrders.SingleOrDefaultAsync(x => x.TenantId == s.TenantId && x.OperationId == r.OperationId, ct); if (old != null) { CreationRules.Require(old.UserId == user.Id && old.Fingerprint == Hash(r), "Purchase replay differs."); return old.Id; } CreationRules.Require(r.OperationId != Guid.Empty, "Stable purchase operation required."); var p = await db.CommerceProducts.SingleOrDefaultAsync(x => x.Id == r.ProductId && x.TenantId == s.TenantId && x.CustomerProductId != null, ct) ?? throw new CoreAccessException(); await Guard(p, ct); CreationRules.Require((p.Kind == "Institutional") == r.InstitutionId.HasValue, "Institutional licenses require their purchasing organization."); if (r.InstitutionId.HasValue) await InstitutionAccess(s, r.InstitutionId.Value, true, ct); var route = await db.CommerceRoutes.SingleOrDefaultAsync(x => x.TenantId == s.TenantId && x.Active && x.Enabled, ct) ?? throw new RuntimeValidationException("Configure a qualified private-test delivery route."); Adapter(route.Adapter); var row = new CommerceOrder { Id = Guid.NewGuid(), TenantId = s.TenantId, UserId = user.Id, OperationId = r.OperationId, Fingerprint = Hash(r), ProductId = p.Id, RouteId = route.Id, InstitutionId = r.InstitutionId }; db.CommerceOrders.Add(row); return row.Id; }, ct);
        var order = await Own(s, id, ct); if (order.PaymentOrderId == null) { var p = await db.CommerceProducts.AsNoTracking().SingleAsync(x => x.Id == order.ProductId, ct); var payment = await customers.CheckoutAsync(s, new(Op(id, "checkout"), p.CustomerProductId!.Value, r.Acquisition), ct); await Change(s.TenantId, async () => { var o = await Own(s, id, ct); CreationRules.Require(o.PaymentOrderId == null || o.PaymentOrderId == payment, "Original payment differs."); o.PaymentOrderId = payment; o.State = "AwaitPayment"; return true; }, ct); }
        await customers.SubmitAsync(s, (await Own(s, id, ct)).PaymentOrderId!.Value, ct); return id;
    }
    private async Task<CommerceOrderView> View(CommerceOrder o, CancellationToken ct) { var p = await db.CommerceProducts.AsNoTracking().SingleAsync(x => x.Id == o.ProductId, ct); var route = await db.CommerceRoutes.AsNoTracking().SingleAsync(x => x.Id == o.RouteId, ct); var d = await db.CommerceDeliveries.AsNoTracking().SingleOrDefaultAsync(x => x.OrderId == o.Id, ct); var payment = o.PaymentOrderId == null ? null : await db.CustomerOrders.AsNoTracking().SingleAsync(x => x.Id == o.PaymentOrderId, ct); return new(o.Id, p.Id, o.PaymentOrderId, o.State, payment?.State ?? "NotSubmitted", d?.State ?? "NotAdmitted", route.Adapter, route.Account, d?.Receipt, p.ContentVersion, p.ContentSha256, Read<CommerceProductRequest>(p.SettingsJson).License, payment?.EndsUtc); }
    public async Task<CommerceOrderView[]> OrdersAsync(CustomerScope s, CancellationToken ct) { var user = await customers.MeAsync(s, ct); var rows = await db.CommerceOrders.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.UserId == user.Id).OrderByDescending(x => x.CreatedUtc).Take(100).ToArrayAsync(ct); var result = new List<CommerceOrderView>(); foreach (var row in rows) result.Add(await View(row, ct)); return result.ToArray(); }
    public async Task<CommerceOrderView> ReconcileAsync(CustomerScope s, Guid id, CancellationToken ct)
    {
        var original = await Own(s, id, ct); CreationRules.Require(original.PaymentOrderId != null, "Resume the original purchase before reconciliation."); await customers.ReconcileAsync(s, original.PaymentOrderId!.Value, ct);
        await Change(s.TenantId, async () =>
        {
            var o = await Own(s, id, ct); var pay = await db.CustomerOrders.AsNoTracking().SingleAsync(x => x.Id == o.PaymentOrderId, ct); var p = await db.CommerceProducts.SingleAsync(x => x.Id == o.ProductId, ct); var r = Read<CommerceProductRequest>(p.SettingsJson); var price = await db.CustomerProducts.AsNoTracking().SingleAsync(x => x.Id == p.CustomerProductId, ct); CreationRules.Require(pay.ProductId == price.Id && pay.UserId == o.UserId && pay.RefundedMinor >= 0, "Original paid product/user binding differs.");
            if (pay.State == "Paid" && pay.RefundedMinor == 0 && pay.EndsUtc > DateTimeOffset.UtcNow)
            {
                await Guard(p, ct); o.State = "Active"; o.EndsUtc = pay.EndsUtc;
                var d = await db.CommerceDeliveries.SingleOrDefaultAsync(x => x.OrderId == o.Id, ct); if (d == null) { var route = await db.CommerceRoutes.AsNoTracking().SingleAsync(x => x.Id == o.RouteId, ct); var did = Guid.NewGuid(); db.CommerceDeliveries.Add(new() { Id = did, TenantId = o.TenantId, OrderId = o.Id, RequestJson = Json(new CommerceDispatch(did, o.Id, o.TenantId, route.Adapter, route.Account, p.ContentSha256, r.License.Mode)) }); }
            }
            else { o.State = pay.RefundedMinor > 0 || pay.State is "Refunded" or "Cancelled" ? "Revoked" : pay.State == "Paid" ? "Expired" : "AwaitPayment"; o.EndsUtc = pay.EndsUtc; }
            return true;
        }, ct);
        var pending = await db.CommerceDeliveries.AsNoTracking().SingleOrDefaultAsync(x => x.OrderId == id, ct);
        if (pending?.State == "Unknown") { var request = Read<CommerceDispatch>(pending.RequestJson); var receipt = await Adapter(request.Adapter).ReconcileAsync(request, ct); await Apply(pending.Id, null, receipt, ct); }
        return await View(await Own(s, id, ct), ct);
    }
    public async Task RefundAsync(CustomerScope s, Guid id, CustomerPaymentAction r, CancellationToken ct) { var o = await Own(s, id, ct); CreationRules.Require(r.Action == "Refund" && o.PaymentOrderId != null, "Refund the original verified payment."); await customers.ChangePaymentAsync(s, o.PaymentOrderId!.Value, r, ct); }
    private async Task<CommerceDownload> Package(CommerceProduct p, CancellationToken ct)
    {
        await Guard(p, ct); var pack = Read<CreationPackage>(p.PackageJson!); var cfg = Read<CommerceProductRequest>(p.SettingsJson); Func<string, string?> encode = System.Net.WebUtility.HtmlEncode;
        var terms = "<section style=\"break-inside:avoid\"><h2>Licensed private test edition</h2><p>Content version " + p.ContentVersion + "; original content hash " + encode(p.ContentSha256) + ".</p><p>License: " + encode(cfg.License.Mode) + "; duration " + cfg.License.Days + " days; seats " + cfg.License.Seats + "; update/correction policy " + encode(cfg.License.UpdatePolicy) + "; contract " + encode(cfg.License.ContractReference) + ".</p><p>" + encode(cfg.License.Disclosure) + "</p></section>";
        var html = pack.Html.Replace("</main>", terms + "</main>", StringComparison.Ordinal);
        return new(p.Id, p.ContentVersion, html, p.ContentSha256, Json(cfg.License), pack.Citations);
    }
    public async Task<CommerceDownload> DownloadAsync(CustomerScope s, Guid id, CancellationToken ct) { var o = await Own(s, id, ct); await CurrentPaid(o, ct); return await Package(await db.CommerceProducts.AsNoTracking().SingleAsync(x => x.Id == o.ProductId, ct), ct); }
    private async Task CurrentPaid(CommerceOrder o, CancellationToken ct) { var pay = await db.CustomerOrders.AsNoTracking().SingleOrDefaultAsync(x => x.Id == o.PaymentOrderId && x.TenantId == o.TenantId && x.UserId == o.UserId, ct); CreationRules.Require(o.State == "Active" && pay is { State: "Paid", RefundedMinor: 0 } && pay.EndsUtc > DateTimeOffset.UtcNow, "Current verified unrefunded license required; client success cannot grant access."); }
}
public static class CommerceServices { public static IServiceCollection AddCommerceWorkbench(this IServiceCollection s) { s.AddScoped<ICommerceWorkbench, CommerceWorkbench>(); s.AddSingleton<ICommerceDeliveryLedger, SqlCommerceDeliveryLedger>(); return s; } }
